832	struct CancellationRequestRecord {
833	    version: &'static str,
834	    control_id: String,
835	    case_id: String,
836	    run_id: String,
837	    plan_item_id: &'static str,
838	    requester: String,
839	    authority_decision_ref: String,
840	    requested_at: String,
841	    ordinal: u64,
842	}
