891	fn record_cancellation(
892	    config: &ServerConfig,
893	    run_id: &str,
894	    case_id: &str,
895	    policy_path: &str,
896	    entity: &str,
897	    process: &str,
898	) -> Result<String, sea_forge_core::ForgeError> {
899	    let policy = agent_probe::resolve_policy_path(&config.root, policy_path);
900	    let bundle = AuthorityPolicyBundle::load(&policy)?;
901	    let engine = PolicyAuthorityEngine::new(bundle.clone())?;
902	    let actor = Actor {
903	        actor_id: entity.into(),
904	        role: ActorRole::Operator,
905	    };
906	    let action = AuthorityAction::Reserved {
907	        resource_type: "run_cancel".into(),
908	        resource_id: run_id.into(),
909	        parameters: serde_json::json!({"process": process}),
910	    };
911	    let ledger = LedgerStream::open(&config.root, format!("case-{case_id}"), "sea-forge-server")?;
912	    let decision = engine.evaluate(AuthorityEvaluation {
913	        actor: &actor,
914	        binding: bundle.resolve_identity(&actor.actor_id, actor.role.clone()),
915	        run_id,
916	        case_id,
917	        plan_item_id: "control_cancel",
918	        sequence: 1,
919	        action: &action,
920	        workspace_root: &config.root,
921	        evidence_refs: vec![],
922	        artifacts_root: None,
923	        timeout_secs: None,
924	        env_keys: Default::default(),
925	        domainforge_candidate: None,
926	        environment: None,
927	    })?;
928	    let authority_ref = agent_probe::commit_view(
929	        &ledger,
930	        "authority_decision",
931	        vec![run_id.into(), "control_cancel".into()],
932	        &decision,
933	        &config
934	            .root
935	            .join("runs")
936	            .join(run_id)
937	            .join("cancellation-authority.json"),
938	        vec![],
939	    )?;
940	    if decision.verdict != Verdict::Allow {
941	        return Err(sea_forge_core::ForgeError::Input(
942	            "cancellation authority denied".into(),
943	        ));
944	    }
945	
946	    let control_id = random_id("cancel")?;
947	    let record = CancellationRequestRecord {
948	        version: "0.2",
949	        control_id: control_id.clone(),
950	        case_id: case_id.into(),
951	        run_id: run_id.into(),
952	        plan_item_id: "agent_task",
953	        requester: entity.into(),
954	        authority_decision_ref: authority_ref.entry_ulid().into(),
955	        requested_at: Utc::now().to_rfc3339(),
956	        ordinal: 1,
957	    };
958	    agent_probe::commit_view(
959	        &ledger,
960	        "control_request",
961	        vec![case_id.into(), run_id.into(), "agent_task".into()],
962	        &record,
963	        &config
964	            .root
965	            .join("runs")
966	            .join(run_id)
967	            .join(format!("control-{control_id}.json")),
968	        vec![authority_ref.entry_ulid().into()],
969	    )?;
970	    Ok(control_id)
971	}
