979	async fn run_cli(_root: &Path, args: &[&str], note: Option<&str>) -> Result<String, String> {
980	    let exe = std::env::current_exe()
981	        .map_err(|e| format!("resolve exe: {e}"))?
982	        .to_string_lossy()
983	        .into_owned();
984	    let cli_exe = {
985	        let p = std::path::PathBuf::from(&exe);
986	        let dir = p.parent().unwrap_or(std::path::Path::new("."));
987	        let cli = dir.join("sea-forge");
988	        if cli.exists() {
989	            cli.to_string_lossy().into_owned()
990	        } else {
991	            exe.clone()
992	        }
993	    };
994	    let mut cmd = Command::new(&cli_exe);
995	    cmd.args(args).stdout(Stdio::piped()).stderr(Stdio::piped());
996	    if let Some(note) = note {
997	        cmd.arg("--note").arg(note);
998	    }
999	    let output = cmd.output().await.map_err(|e| format!("spawn: {e}"))?;
1000	    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
1001	    if !output.status.success() {
1002	        let stderr = String::from_utf8_lossy(&output.stderr);
1003	        return Err(format!("exit {:?}: {stderr}", output.status.code()));
1004	    }
1005	    Ok(stdout)
1006	}
1007	
1008	fn fire_notify(argv: &[String], event: serde_json::Value) -> Result<(), String> {
1009	    if argv.is_empty() {
1010	        return Ok(());
1011	    }
1012	    let mut cmd = std::process::Command::new(&argv[0]);
1013	    cmd.args(&argv[1..]);
1014	    cmd.stdin(Stdio::piped())
1015	        .stdout(Stdio::piped())
1016	        .stderr(Stdio::piped());
1017	    let mut child = cmd.spawn().map_err(|e| format!("spawn notify: {e}"))?;
1018	    if let Some(mut stdin) = child.stdin.take() {
1019	        use std::io::Write;
1020	        let _ = serde_json::to_writer(&mut stdin, &event);
1021	        let _ = stdin.write_all(b"\n");
1022	    }
1023	    let _ = child.wait();
1024	    Ok(())
1025	}
